export type PostTag = { label: string; slug: string };

/** Thông tin rút gọn của một bài — đủ cho sidebar "Bài viết mới nhất" và "Bài viết liên quan". */
export type PostSummary = {
  slug: string;
  title: string;
  category: string;
  readMinutes: number;
  /** Ngày đăng dạng tiếng Việt như site gốc, vd. "6 thg 10, 2026". */
  publishedLabel: string;
  image: string;
  /** Alt ảnh (mặc định = tiêu đề). */
  imageAlt?: string;
};

export type Post = PostSummary & {
  excerpt: string;
  /** Nhãn tháng/năm trên thẻ "review tile", vd. "Oct 2026". */
  dateLabel: string;
  categorySlug: string;
  tags: PostTag[];
  /** Nội dung bài (HTML rich-text từ CMS của site gốc — nội dung tin cậy của chính mình). */
  bodyHtml?: string;
};

